rss.channel:
{{ .Site.Title }}
{{ .Permalink }}
{{ .Site.Params.description }}
{{ .Site.Language.Locale }}
{{ with .OutputFormats.Get "RSS" }}{{ end }}
{{ range first 30 (where (where .Site.RegularPages "Section" "posts") "Params.hidden" "ne" true).ByDate.Reverse }}


  {{ .Title }}{{ .Permalink }}{{ .Permalink }}
